/* ---------- Basis-UI ---------- */
const header=$('#top'), prog=$('#prog');
function onScroll(){
  const y=scrollY, h=document.documentElement.scrollHeight-innerHeight;
  header.classList.toggle('scrolled',y>40);
  prog.style.transform='scaleX('+(h>0?Math.min(1,y/h):0)+')';
  if(!RM&&y<1400) $$('[data-par]').forEach(e=>{e.style.transform='translateY('+(-y*e.dataset.par)+'px)'});
  const s=$('#sticky'); s.classList.toggle('show',document.body.dataset.view==='course'&&y>420);
}
addEventListener('scroll',()=>requestAnimationFrame(onScroll),{passive:true});

const root=document.documentElement;
$('#themeBtn').addEventListener('click',()=>{
  const dark=root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme: dark)').matches;
  root.dataset.theme=dark?'light':'dark';
});
const drawer=$('#drawer'),burger=$('#burger');
function setDrawer(o){drawer.classList.toggle('open',o);burger.setAttribute('aria-expanded',o);document.body.style.overflow=o?'hidden':''; if(o)$('#closeDrawer').focus(); else if(document.activeElement&&drawer.contains(document.activeElement))burger.focus()}
burger.addEventListener('click',()=>setDrawer(true));
$('#closeDrawer').addEventListener('click',()=>setDrawer(false));
drawer.addEventListener('click',e=>{if(e.target.closest('a'))setDrawer(false)});
addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('open'))setDrawer(false)});

let toastT;function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastT);toastT=setTimeout(()=>el.classList.remove('show'),3200)}

/* Reveal + Spotlight */
const io='IntersectionObserver' in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -4% 0px'}):null;
function initReveal(r){$$('.rv:not(.in)',r).forEach(e=>io?io.observe(e):e.classList.add('in'))}
document.addEventListener('pointermove',e=>{const c=e.target.closest&&e.target.closest('.card');if(c){const b=c.getBoundingClientRect();c.style.setProperty('--mx',(e.clientX-b.left)+'px');c.style.setProperty('--my',(e.clientY-b.top)+'px')}});

/* Akkordeon */
function acc(items,numbered){
  const N=acc.n++;
  return items.map((it,i)=>'<div class="ai"><h3><button class="q" type="button" aria-expanded="false" aria-controls="ac'+N+'-'+i+'" id="ab'+N+'-'+i+'"><span>'+(numbered?'<span class="num">'+String(i+1).padStart(2,'0')+'</span>':'')+it.q+(it.ph?' <span class="ph">Platzhalter</span>':'')+'</span><span class="pm" aria-hidden="true"></span></button></h3><div class="a" id="ac'+N+'-'+i+'" role="region" aria-labelledby="ab'+N+'-'+i+'"><div><p>'+it.a+'</p></div></div></div>').join('');
}
acc.n=0;
document.addEventListener('click',e=>{
  const b=e.target.closest('button.q');if(!b)return;
  const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',!open);
  $('#'+b.getAttribute('aria-controls')).classList.toggle('open',!open);
});

