/* ---------- Kursfinder ---------- */
const FQ=[
 {q:'Was beschäftigt dich gerade am meisten?',o:[['Ich möchte mich persönlich weiterentwickeln.',[2,0,0]],['Ich möchte ein Business aufbauen oder verbessern.',[0,2,0]],['Ich möchte meinen Alltag besser organisieren.',[0,0,2]],['Ich interessiere mich für mehrere Themen.',[1,1,1]]]},
 {q:'Was wünschst du dir als nächsten Schritt?',o:[['Mehr Klarheit und Selbstvertrauen',[2,0,0]],['Konkrete unternehmerische Fähigkeiten',[0,2,0]],['Mehr Struktur und Freiraum im Alltag',[0,0,2]],['Eine Kombination aus mehreren Bereichen',[1,1,1]]]},
 {q:'Wie möchtest du starten?',o:[['Mit einem klaren Schwerpunkt','one'],['Mit mehreren Themen','two'],['Ich möchte mich erst orientieren','all']]}
];
const WHY=['mehr Klarheit und Selbstvertrauen entwickeln','unternehmerische Fähigkeiten aufbauen und deine Idee strukturieren','deinen Alltag so organisieren, dass auch deine eigenen Ziele Platz haben'];
const fs={step:0,ans:[null,null,null]};
const fbox=$('#fbox');
function renderFinder(){
  if(fs.step>=3)return renderResult();
  const q=FQ[fs.step], sel=fs.ans[fs.step];
  fbox.innerHTML='<div class="fprog"><span>Frage '+(fs.step+1)+' von 3</span><div class="track" role="progressbar" aria-valuemin="0" aria-valuemax="3" aria-valuenow="'+fs.step+'"><div class="fill" style="width:'+(fs.step/3*100)+'%"></div></div></div>'+
  '<fieldset><legend>'+q.q+'</legend>'+q.o.map((o,i)=>'<label class="opt"><input type="radio" name="fq'+fs.step+'" value="'+i+'"'+(sel===i?' checked':'')+'><span>'+o[0]+'</span></label>').join('')+'</fieldset>'+
  '<div class="fnav"><button class="btn ghost sm" type="button" id="fBack"'+(fs.step===0?' disabled':'')+'>Zurück</button><button class="btn sm" type="button" id="fNext"'+(sel===null?' disabled':'')+'>'+(fs.step===2?'Ergebnis zeigen':'Weiter')+'</button></div>';
  requestAnimationFrame(()=>{const f=$('.fill',fbox);if(f)f.style.width=((fs.step+(sel!==null?1:0))/3*100)+'%'});
  $$('input',fbox).forEach(i=>i.addEventListener('change',()=>{fs.ans[fs.step]=+i.value;$('#fNext').disabled=false;$('.fill',fbox).style.width=((fs.step+1)/3*100)+'%';if(fs.step===0&&fs.ans.slice(1).every(x=>x===null))track('course_finder_start')}));
  $('#fBack').addEventListener('click',()=>{if(fs.step>0){fs.step--;renderFinder()}});
  $('#fNext').addEventListener('click',()=>{if(fs.ans[fs.step]!==null){fs.step++;renderFinder()}});
}
function finderResult(ans){
  const sc=[0,0,0];[0,1].forEach(i=>FQ[i].o[ans[i]][1].forEach((v,k)=>sc[k]+=v));
  const mode=FQ[2].o[ans[2]][1];
  const order=[0,1,2].sort((a,b)=>sc[b]-sc[a]);
  const allEq=sc[0]===sc[1]&&sc[1]===sc[2];
  let picks;
  if(mode==='all'||allEq) picks=order;
  else if(mode==='one'){picks=[order[0]];if(sc[order[1]]===sc[order[0]])picks.push(order[1]);if(picks.length>1&&sc[order[2]]===sc[order[0]])picks.push(order[2])}
  else{picks=[order[0],order[1]];if(sc[order[2]]===sc[order[1]])picks.push(order[2])}
  let why;
  if(picks.length===3){why=(allEq||mode!=='all')?'Deine Antworten zeigen keinen einzelnen Schwerpunkt.':'Du möchtest dich zuerst orientieren.';why+=' Deshalb zeigen wir dir alle drei Masterclasses mit einer kurzen Einordnung. Du kannst überall hineinschauen und dann entscheiden.'}
  else why='Deine Antworten deuten darauf hin, dass du vor allem '+picks.map(k=>WHY[k]).join(' und ')+' möchtest. Deshalb '+(picks.length===1?'könnte die Masterclass «'+COURSES[picks[0]].title+'» ein passender Einstieg sein.':'könnten die Masterclasses '+picks.map(k=>'«'+COURSES[k].title+'»').join(' und ')+' passende Einstiege sein.');
  return{picks,why,sc};
}
function renderResult(){
  const r=finderResult(fs.ans);track('course_finder_complete',{picks:r.picks});
  fbox.innerHTML='<div class="fprog"><span>Dein Ergebnis</span><div class="track"><div class="fill" style="width:100%"></div></div></div><div class="res"><p class="why">'+r.why+'</p>'+r.picks.map(k=>{const c=COURSES[k];return '<div class="rcard"><span class="nr">MASTERCLASS '+c.nr+'</span><h4>'+c.title+'</h4><p>'+c.benefit+'</p><a class="btn sm" href="#'+c.slug+'">'+c.cta+' '+ARROW+'</a></div>'}).join('')+'</div><div class="fnav"><button class="btn ghost sm" type="button" id="fBack">Antworten ändern</button><button class="btn ghost sm" type="button" id="fReset">Neu starten</button></div>';
  $('#fBack').addEventListener('click',()=>{fs.step=2;renderFinder()});
  $('#fReset').addEventListener('click',()=>{fs.step=0;fs.ans=[null,null,null];renderFinder()});
}
renderFinder();

