  <section><div class="wrap two"><div class="rv"><p class="eyebrow">FAQ zu diesem Kurs</p><h2 class="h2" style="margin-top:14px">Häufige Fragen.</h2></div><div class="acc rv" style="--i:1">${acc(c.faq.map(f=>({q:f[0],a:f[1]})))}</div></div></section>
